// The rack and the experiment share one bench, following ch2 card 02.
export const sampleNames=['鎂帶','含水硫酸銅','兩種溶液','石灰石＋鹽酸'];
const observations={light:'銀白色鎂帶 → 白色氧化鎂；發光、放熱',color:'藍色晶體 → 白色無水硫酸銅',solid:'兩種無色溶液 → 白色碳酸鈣沉澱',gas:'石灰石遇稀鹽酸 → 產生氣泡'};
export function reactionSampleIcon(id){
 const glass='fill="#eff9f5" fill-opacity=".65" stroke="#78988a" stroke-width="1.3"';
 const bottle=(x,label)=>`<path d="M${x+8} 16h16v12l8 9v37q-16 6-32 0V37l8-9Z" ${glass}/><path d="M${x+2} 49h28v23q-14 4-28 0Z" fill="#c1dcd4" fill-opacity=".55"/><path d="M${x+7} 12h18v8H${x+7}Z" fill="#9cad98"/><rect x="${x+3}" y="44" width="26" height="20" rx="2" fill="#fffdef"/><text x="${x+16}" y="57" text-anchor="middle" font-size="8" fill="#45674f">${label}</text>`;
 const art=id==='light'?'<ellipse cx="50" cy="74" rx="37" ry="9" fill="#fffef6" stroke="#b1bba9"/><path d="M23 65l12-13 14 15 14-15 14 13" fill="none" stroke="#6d8385" stroke-width="9" stroke-linejoin="bevel"/><path d="M23 62l12-13 14 15 14-15 14 13" fill="none" stroke="#e5ebeb" stroke-width="5" stroke-linejoin="bevel"/>':id==='color'?'<ellipse cx="50" cy="71" rx="37" ry="12" fill="#fffef6" stroke="#b1bba9"/>'+Array.from({length:12},(_,i)=>`<path d="M${24+i*17%47} ${58+i*7%12}l7-9 9 5-5 10Z" fill="${i%2?'#5db9df':'#3c8eb9'}" stroke="#c1eff6" stroke-width=".7"/>`).join(''):id==='solid'?bottle(9,'Na₂CO₃')+bottle(58,'CaCl₂'):'<ellipse cx="40" cy="73" rx="29" ry="9" fill="#f9f9ed" stroke="#b1bba9"/><path d="M18 69l3-17 18-8 18 10 4 16-24 6Z" fill="#ded8c7" stroke="#b3b4a4"/><path d="M22 53l14 7 20-5M36 60v14" fill="none" stroke="#f8f5e8"/><path d="M76 19v41l-4 13-4-13V19" '+glass+'/><rect x="65" y="6" width="14" height="23" rx="7" fill="#ac7159"/>';
 return `<svg viewBox="0 0 100 90" aria-hidden="true">${art}</svg>`;
}
export function reactionRecords(demonstrations,seen){return '<h4>我的觀察紀錄 <span>'+demonstrations.filter(d=>seen.has(d.id)).length+' / 4</span></h4><div class="observation-table"><table><thead><tr><th>實驗</th><th>觀察到的變化</th></tr></thead><tbody>'+demonstrations.map(d=>'<tr><th scope="row">'+d.name+'</th><td class="'+(seen.has(d.id)?'recorded':'')+'">'+(seen.has(d.id)?'✓ '+observations[d.id]:'尚未觀察')+'</td></tr>').join('')+'</tbody></table></div>';}
export function reactionLabMarkup(demonstrations){return `<div class="observation-lab integrated-studio"><aside class="phenomena-tabs specimen-shelf" aria-label="實驗樣本架"><div class="shelf-heading"><b>實驗樣本架</b><span>點選取用，或拖到操作台</span></div><div class="shelf-rail">${demonstrations.map((d,i)=>`<button type="button" class="reaction-sample shelf-specimen" data-demo="${i}" aria-pressed="${i===0}" aria-label="取用${sampleNames[i]}"><span class="specimen-vial">${reactionSampleIcon(d.id)}</span><b>${sampleNames[i]}</b><small>${d.title}</small><span class="sample-observed" hidden>✓ 已觀察</span></button>`).join('')}</div></aside><div class="bench-workspace"><div class="reaction-workflow"></div><div class="reaction-theater"><div class="reaction-stage"><div class="reaction-stage-head"><h3 class="reaction-name"></h3><b class="reaction-phase"></b></div><div class="reaction-interactive-scene"><div class="reaction-art"></div><div class="reaction-instruments"><div class="reaction-drop-target" aria-hidden="true" hidden>放入燒杯</div><div class="sample-load-zone" aria-hidden="true" hidden>放入樣本</div><button type="button" class="lamp-grab" aria-label="點燃酒精燈"><span>點燃酒精燈</span></button><button type="button" class="reagent-grab sodium-grab" data-practice-tool="sodium" aria-label="加入碳酸鈉溶液，亦可拖到燒杯"><span>碳酸鈉</span></button><button type="button" class="reagent-grab calcium-grab" data-practice-tool="calcium" aria-label="加入氯化鈣溶液，亦可拖到燒杯"><span>氯化鈣</span></button><button type="button" class="dropper-grab" data-practice-tool="dropper"><span>移到燒杯上方</span></button></div></div><progress max="1" value="0" aria-label="反應進度"></progress><div class="reaction-instruction" role="status" aria-live="polite"><span aria-hidden="true">↗</span><b class="hands-on-hint"></b></div><div class="reaction-notes"><div class="reaction-observation" role="status" aria-live="polite"></div><div class="practice-controls"><div class="dropper-actions"><p class="drop-count"></p><button type="button" class="primary squeeze-dropper">按住連續滴加</button></div></div></div><div class="reaction-transport"><button type="button" class="primary demonstrate"></button><button type="button" class="secondary view-comparison" hidden>比較反應前後 ↓</button><button type="button" class="secondary next-reaction" hidden></button><button type="button" class="text-button reaction-rewind">重新實驗</button></div></div></div><details class="reaction-science"><summary>反應式與提醒</summary><div class="reaction-equation"></div><p class="reaction-note"></p></details></div></div><section class="reaction-comparison" aria-label="反應前後的物質變化對照" hidden></section><section class="reaction-records" aria-label="我的觀察紀錄"></section><p class="lab-safety">教學模擬；實際實驗須由教師指導。勿直視燃燒的鎂。</p>`;}
